enum Device {
    case phone(model: String)
    case laptop(ramGB: Int)
}
func describe(_ device: Device) -> String {
    switch device {
    case .phone(let model):
        return "Phone: \(model)"
    case .laptop(let ram):
        return "Laptop with \(ram)GB"
    }
}
print(describe(.phone(model: "Air")))

