enum Speed {
    case slow, medium, fast
    var milesPerHour: Int {
        switch self {
        case .slow: return 25
        case .medium: return 45
        case .fast: return 65
        }
    }
}
let currentSpeed = Speed.fast
print(currentSpeed.milesPerHour)

enum Beverage: CaseIterable {
    case coffee, tea, water
}
print(Beverage.allCases.count)

enum ResultState {
    case success(count: Int)
    case failure(message: String)
}
func report(_ state: ResultState) -> String {
    switch state {
    case .success(let count) where count > 10:
        return "High success"
    case .success:
        return "Normal success"
    case .failure:
        return "Failed"
    }
}
print(report(.success(count: 15)))

