enum Coin: Int {
    case penny = 1
    case nickel = 5
    case dime = 10
    case quarter = 25
}
if let coin = Coin(rawValue: 10) {
    print(coin.rawValue)
}

enum FileStatus {
    case pending
    case uploading(progress: Int)
    case failed(error: String)
}
func describeStatus(_ status: FileStatus) -> String {
    switch status {
    case .pending:
        return "Pending"
    case .uploading(let progress):
        return "Uploading: \(progress)%"
    case .failed(let error):
        return "Failed: \(error)"
    }
}
print(describeStatus(.uploading(progress: 75)))
